47	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
48	import org.springframework.samples.petclinic.service.ClinicService;
49	import org.springframework.security.access.prepost.PreAuthorize;
50	import org.springframework.web.bind.annotation.CrossOrigin;
51	import org.springframework.web.bind.annotation.RequestMapping;
52	import org.springframework.web.bind.annotation.RestController;
53	import org.springframework.web.util.UriComponentsBuilder;
54	
55	import jakarta.transaction.Transactional;
56	
57	/**
58	 * @author Vitaliy Fedoriv
59	 */
60	
61	@RestController
62	@CrossOrigin(exposedHeaders = "errors, content-type")
63	@RequestMapping("/api")
64	public class OwnerRestControllerV1 implements OwnersApi {
65	
66	    private final ClinicService clinicService;
67	
68	    private final OwnerMapper ownerMapper;
69	
70	    private final PetMapper petMapper;
71	
72	    private final VisitMapper visitMapper;
73	
74	    public OwnerRestControllerV1(ClinicService clinicService,
75	                                 OwnerMapper ownerMapper,
76	                                 PetMapper petMapper,
77	                                 VisitMapper visitMapper) {
78	        this.clinicService = clinicService;
79	        this.ownerMapper = ownerMapper;
80	        this.petMapper = petMapper;
81	        this.visitMapper = visitMapper;
82	    }
83	
84	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
85	    @Override
86	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
87	        Collection<Owner> owners;
88	        if (lastName != null) {
89	            owners = this.clinicService.findOwnerByLastName(lastName);
90	        } else {
91	            owners = this.clinicService.findAllOwners();
92	        }
93	        if (owners.isEmpty()) {
94	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
95	        }
96	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
97	    }
98	
99	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
100	    @Override
101	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
102	        Owner owner = this.clinicService.findOwnerById(ownerId);
103	        if (owner == null) {
104	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
105	        }
106	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
107	    }
108	
109	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
110	    @Override
111	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
112	        // Normalize the address up front so every downstream use (the required-field check,
113	        // household-duplicate detection, the shared household id and the stored/returned value)
114	        // works from the same canonical form.
115	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
116	        List<String> missingFields = new ArrayList<>();
117	        if (isBlank(ownerFieldsDto.getFirstName())) {
118	            missingFields.add("firstName");
119	        }
120	        if (isBlank(ownerFieldsDto.getLastName())) {
121	            missingFields.add("lastName");
122	        }
123	        // Reject an address that is blank once normalized (e.g. whitespace-only input).
124	        if (isBlank(normalizedAddress)) {
125	            missingFields.add("address");
126	        }
127	        if (isBlank(ownerFieldsDto.getCity())) {
128	            missingFields.add("city");
129	        }
130	        if (isBlank(ownerFieldsDto.getTelephone())) {
131	            missingFields.add("telephone");
132	        }
133	        if (!missingFields.isEmpty()) {
134	            throw new InvalidOwnerFieldsException(missingFields);
135	        }
136	        // Normalize the telephone into E.164 form; a number that cannot form a valid
137	        // E.164 value is rejected with a 400.
138	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
139	        // Email is optional; when present it must be a syntactically valid address and is
140	        // stored lower-cased. An invalid address is rejected with a 400.
141	        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
142	        // Reject the request if the E.164 telephone is already used by any other owner.
143	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
144	            .map(Owner::getTelephone)
145	            .filter(existing -> existing != null)
146	            .anyMatch(normalizedTelephone::equals);
147	        if (telephoneInUse) {
148	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
149	        }
150	        // Household handling for a matching last name + address (compared case-insensitively with
151	        // collapsed whitespace). By default such a request is rejected as a duplicate household;
152	        // when the caller opts in via 'sharesHousehold' the owner is instead admitted into the shared
153	        // household and every member (the new owner and any existing ones) is stamped with the same
154	        // stable 'householdId'.
155	        String normalizedLastName = collapse(ownerFieldsDto.getLastName());
156	        String householdId = null;
157	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
158	            householdId = householdId(normalizedLastName, normalizedAddress);
159	            // Backfill the shared identifier onto any existing member of this household so the whole
160	            // household carries the same stable value.
161	            for (Owner existing : this.clinicService.findAllOwners()) {
162	                if (collapse(existing.getLastName()).equals(normalizedLastName)
163	                    && normalizeAddress(existing.getAddress()).equals(normalizedAddress)
164	                    && !householdId.equals(existing.getHouseholdId())) {
165	                    existing.setHouseholdId(householdId);
166	                    this.clinicService.saveOwner(existing);
167	                }
168	            }
169	        } else {
170	            boolean householdInUse = this.clinicService.findAllOwners().stream()
171	                .anyMatch(existing -> collapse(existing.getLastName()).equals(normalizedLastName)
172	                    && normalizeAddress(existing.getAddress()).equals(normalizedAddress));
173	            if (householdInUse) {
174	                throw new DuplicateOwnerHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
175	            }
176	        }
177	        HttpHeaders headers = new HttpHeaders();
178	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
179	        owner.setAddress(normalizedAddress);
180	        owner.setTelephone(normalizedTelephone);
181	        owner.setEmail(normalizedEmail);
182	        owner.setHouseholdId(householdId);
183	        // Record how many existing owners (before this create) share this owner's first and last
184	        // name, compared case-insensitively. Computed against the current owners so the new owner
185	        // itself is never counted.
186	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
187	        // When no registration date is supplied, default it to the server's current date.
188	        if (owner.getRegistrationDate() == null) {
189	            owner.setRegistrationDate(LocalDate.now());
190	        }
191	        // Assign the customer code: '<CITY3>-<LAST3>-<NNNN>' where CITY3 is the upper-cased first
192	        // three letters of the city, LAST3 the upper-cased first three letters of the last name and
193	        // NNNN is a per-city 4-digit zero-padded sequence equal to one more than the number of
194	        // owners already in that city.
195	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
196	        this.clinicService.saveOwner(owner);
197	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
198	        headers.setLocation(UriComponentsBuilder.newInstance()
199	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
200	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
201	    }
202	
203	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
204	    @Override
205	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
206	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
207	        if (currentOwner == null) {
208	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
209	        }
210	        currentOwner.setAddress(ownerFieldsDto.getAddress());
211	        currentOwner.setCity(ownerFieldsDto.getCity());
212	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
213	        currentOwner.setLastName(ownerFieldsDto.getLastName());
214	        currentOwner.setTelephone(toE164(ownerFieldsDto.getTelephone()));
215	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
216	        this.clinicService.saveOwner(currentOwner);
217	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
218	    }
219	
220	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
221	    @Transactional
222	    @Override
223	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
224	        Owner owner = this.clinicService.findOwnerById(ownerId);
225	        if (owner == null) {
226	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
227	        }
228	        this.clinicService.deleteOwner(owner);
229	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
230	    }
231	
232	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
233	    @Override
234	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
235	        Owner owner = this.clinicService.findOwnerById(ownerId);
236	        if (owner == null) {
237	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
238	        }
239	        HttpHeaders headers = new HttpHeaders();
240	        Pet pet = petMapper.toPet(petFieldsDto);
241	        owner.setId(ownerId);
242	        pet.setOwner(owner);
243	        pet.getType().setName(null);
244	        this.clinicService.savePet(pet);
245	        PetDto petDto = petMapper.toPetDto(pet);
246	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
247	            .buildAndExpand(pet.getId()).toUri());
248	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
249	    }
250	
251	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
252	    @Override
253	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
254	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
255	        if (currentOwner != null) {
256	            Pet currentPet = this.clinicService.findPetById(petId);
257	            if (currentPet != null) {
258	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
259	                currentPet.setName(petFieldsDto.getName());
260	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
261	                this.clinicService.savePet(currentPet);
262	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
263	            }
264	        }
265	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
266	    }
267	
268	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
269	    @Override
270	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
271	        HttpHeaders headers = new HttpHeaders();
272	        Visit visit = visitMapper.toVisit(visitFieldsDto);
273	        Pet pet = new Pet();
274	        pet.setId(petId);
275	        visit.setPet(pet);
276	        this.clinicService.saveVisit(visit);
277	        VisitDto visitDto = visitMapper.toVisitDto(visit);
278	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
279	            .buildAndExpand(visit.getId()).toUri());
280	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
281	    }
282	
283	
284	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
285	    @Override
286	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
287	        Owner owner = this.clinicService.findOwnerById(ownerId);
288	        if (owner != null) {
289	            Pet pet = owner.getPet(petId);
290	            if (pet != null) {
291	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
292	            }
293	        }
294	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
295	    }
296	
297	    private static boolean isBlank(String value) {
298	        return value == null || value.trim().isEmpty();
299	    }
300	
301	    /**
302	     * Normalize an owner identity field for household-duplicate comparison: trim, collapse every
303	     * run of whitespace to a single space, and lower-case. Used so that last name and address are
304	     * compared case-insensitively with collapsed whitespace.
305	     */
306	    private static String collapse(String value) {
307	        if (value == null) {
308	            return "";
309	        }
310	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
311	    }
312	
313	    /**
314	     * Common street-type abbreviations expanded during address normalization.
315	     */
316	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
317	        "ST", "STREET",
318	        "RD", "ROAD",
319	        "AVE", "AVENUE");
320	
321	    /**
322	     * Normalize an owner address into its canonical stored/compared form: trim, collapse every run
323	     * of whitespace to a single space, upper-case, and expand common street-type abbreviations
324	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). Returns an empty string for
325	     * a {@code null} or blank input. The transformation is idempotent, so an already-normalized
326	     * address maps to itself.
327	     */
328	    private static String normalizeAddress(String value) {
329	        if (value == null) {
330	            return "";
331	        }
332	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
333	        if (collapsed.isEmpty()) {
334	            return "";
335	        }
336	        String[] tokens = collapsed.split(" ");
337	        StringBuilder sb = new StringBuilder(collapsed.length());
338	        for (int i = 0; i < tokens.length; i++) {
339	            if (i > 0) {
340	                sb.append(' ');
341	            }
342	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
343	        }
344	        return sb.toString();
345	    }
346	
347	    /**
348	     * Derive the stable household identifier shared by owners with the same normalized last name
349	     * and address. It is a deterministic function of those two values, so every member of a
350	     * household independently derives the same identifier: the first 12 upper-case hex characters
351	     * of {@code SHA-256(normalizedLastName + '\n' + normalizedAddress)}.
352	     */
353	    private static String householdId(String normalizedLastName, String normalizedAddress) {
354	        try {
355	            byte[] digest = MessageDigest.getInstance("SHA-256")
356	                .digest((normalizedLastName + "\n" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
357	            StringBuilder sb = new StringBuilder(digest.length * 2);
358	            for (byte b : digest) {
359	                sb.append(String.format("%02x", b));
360	            }
361	            return sb.substring(0, 12).toUpperCase();
362	        }
363	        catch (NoSuchAlgorithmException e) {
364	            throw new IllegalStateException("SHA-256 not available", e);
365	        }
366	    }
367	
368	    /**
369	     * Build the customer code for a new owner: {@code '<CITY3>-<LAST3>-<NNNN>'} where CITY3 is the
370	     * upper-cased first three letters of the city, LAST3 the upper-cased first three letters of the
371	     * last name and NNNN is a per-city 4-digit zero-padded sequence equal to one more than the
372	     * number of owners already in that city (e.g. {@code 'SYD-SMI-0007'}).
373	     */
374	    /**
375	     * Count the existing owners that share the given first and last name, compared
376	     * case-insensitively. Called before the new owner is saved, so the returned value reflects the
377	     * namesakes that already existed at creation time (the new owner itself is not included).
378	     */
379	    private int countNamesakes(String firstName, String lastName) {
380	        return (int) this.clinicService.findAllOwners().stream()
381	            .filter(existing -> existing.getFirstName() != null && existing.getLastName() != null)
382	            .filter(existing -> existing.getFirstName().equalsIgnoreCase(firstName)
383	                && existing.getLastName().equalsIgnoreCase(lastName))
384	            .count();
385	    }
386	
387	    private String nextCustomerCode(String city, String lastName) {
388	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
389	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
390	        long sequence = this.clinicService.findAllOwners().stream()
391	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
392	            .count() + 1L;
393	        return String.format("%s-%s-%04d", city3, last3, sequence);
394	    }
395	
396	    /**
397	     * Convert a raw telephone into E.164 form. Spaces, dashes and brackets are stripped. A leading
398	     * {@code '+'} with its country code is preserved; otherwise the Australian country code
399	     * {@code '+61'} is assumed and a single leading {@code '0'} is dropped from the national digits.
400	     * The result must be a {@code '+'} followed by 8 to 15 digits, otherwise an
401	     * {@link InvalidOwnerFieldsException} is thrown so the request is rejected with a 400.
402	     */
403	    private static String toE164(String raw) {
404	        String cleaned = raw.trim().replaceAll("[\\s()\\-]", "");
405	        boolean hasCountryCode = cleaned.startsWith("+");
406	        String digits = hasCountryCode ? cleaned.substring(1) : cleaned;
407	        if (!digits.matches("\\d+")) {
408	            throw new InvalidOwnerFieldsException(List.of("telephone"));
409	        }
410	        if (!hasCountryCode) {
411	            if (digits.startsWith("0")) {
412	                digits = digits.substring(1);
413	            }
414	            digits = "61" + digits;
415	        }
416	        if (digits.length() < 8 || digits.length() > 15) {
417	            throw new InvalidOwnerFieldsException(List.of("telephone"));
418	        }
419	        return "+" + digits;
420	    }
421	
422	    /**
423	     * Pragmatic syntactic check for an email address: a non-empty local part, an {@code @},
424	     * and a domain with at least one dot-separated label, none of which contain whitespace or
425	     * a second {@code @}. This is deliberately permissive but rejects obviously malformed input.
426	     */
427	    private static final Pattern EMAIL_PATTERN =
428	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
429	
430	    /**
431	     * Validate and normalize an optional owner email. Returns {@code null} when no email was
432	     * supplied (the field is optional). When supplied it must be a syntactically valid address,
433	     * otherwise an {@link InvalidOwnerFieldsException} is thrown so the request is rejected with a
434	     * 400. A valid address is returned lower-cased.
435	     */
436	    private static String normalizeEmail(String email) {
437	        if (email == null || email.isEmpty()) {
438	            return null;
439	        }
440	        String trimmed = email.trim();
441	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
442	            throw new InvalidOwnerFieldsException(List.of("email"));
443	        }
444	        return trimmed.toLowerCase();
445	    }
446	}
