package org.springframework.samples.petclinic.rest.advice;

/**
 * Thrown when a request to create an owner names a city that already contains the maximum number
 * of owners (50). The city is considered full and no further owners may be registered in it, so
 * the request is rejected. Carries the offending city so the REST response can report it.
 */
public class CityAtCapacityException extends RuntimeException {

    private final String city;

    public CityAtCapacityException(String city) {
        super("The city has reached its maximum number of owners: " + city);
        this.city = city;
    }

    public String getCity() {
        return this.city;
    }
}

